terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Credentials come from AWS_PROFILE=mc-admin (IAM Identity Center SSO).
# Never put access keys here, and never use root keys.
provider "aws" {
  # Must be the Identity Center home Region, or the ssoadmin calls fail
  region = var.region

  default_tags {
    tags = {
      Project = "aws-safe-setup"
      Owner   = "masterclass-learner"
    }
  }
}

# Used to read the 12-digit account ID for budgets and assignments
data "aws_caller_identity" "current" {}

variable "region" {
  description = "Home Region of IAM Identity Center, e.g. ap-south-1 (Mumbai)"
  type        = string
  default     = "ap-south-1"
}

variable "alert_email" {
  description = "Email address that receives the budget alerts"
  type        = string
}

variable "budget_limit_usd" {
  description = "Monthly cost budget in USD (the hands-on task uses 5)"
  type        = string
  default     = "5"
}

variable "sso_user_name" {
  description = "Identity Center user name created in the console (README step A5)"
  type        = string
  default     = "learner"
}

output "account_id" {
  value = data.aws_caller_identity.current.account_id
}

output "daily_permission_set_arn" {
  value = aws_ssoadmin_permission_set.daily.arn
}

# Reads the Identity Center instance that you enabled in the console
data "aws_ssoadmin_instances" "this" {}

locals {
  instance_arn      = tolist(data.aws_ssoadmin_instances.this.arns)[0]
  identity_store_id = tolist(data.aws_ssoadmin_instances.this.identity_store_ids)[0]
}

# Finds the existing user 'learner' by user name
data "aws_identitystore_user" "learner" {
  identity_store_id = local.identity_store_id

  alternate_identifier {
    unique_attribute {
      attribute_path  = "UserName"
      attribute_value = var.sso_user_name
    }
  }
}

# Least privilege for daily labs: all services except IAM management
resource "aws_ssoadmin_permission_set" "daily" {
  name             = "DailyWork"
  description      = "Daily study work without IAM admin rights"
  instance_arn     = local.instance_arn
  session_duration = "PT8H" # credentials expire after 8 hours
}

resource "aws_ssoadmin_managed_policy_attachment" "daily_poweruser" {
  instance_arn       = local.instance_arn
  permission_set_arn = aws_ssoadmin_permission_set.daily.arn
  managed_policy_arn = "arn:aws:iam::aws:policy/PowerUserAccess"
}

# Gives 'learner' the DailyWork role in this account
resource "aws_ssoadmin_account_assignment" "learner_daily" {
  instance_arn       = local.instance_arn
  permission_set_arn = aws_ssoadmin_permission_set.daily.arn
  principal_id       = data.aws_identitystore_user.learner.user_id
  principal_type     = "USER"
  target_id          = data.aws_caller_identity.current.account_id
  target_type        = "AWS_ACCOUNT"

  # Attach the policy first so the role is not empty when it is created
  depends_on = [aws_ssoadmin_managed_policy_attachment.daily_poweruser]
}

