# Inputs for the project. Change them with -var or a terraform.tfvars file.

variable "region" {
  description = "AWS Region for the S3 bucket (Mumbai by default)"
  type        = string
  default     = "ap-south-1"
}

variable "project" {
  description = "Name prefix used for all resources"
  type        = string
  default     = "clf-static-site"
}

variable "monthly_budget_usd" {
  description = "Monthly cost budget in USD for the alert"
  type        = string
  default     = "5"
}

variable "alert_email" {
  description = "Email address that receives budget alerts"
  type        = string
}

terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = { Project = var.project } # tags help you filter costs in Cost Explorer
  }
}

# The bucket holds the site files. bucket_prefix makes the name globally unique.
resource "aws_s3_bucket" "site" {
  bucket_prefix = "${var.project}-"
  force_destroy = true # lets terraform destroy delete a bucket that still has objects
}

# Your part of shared responsibility: keep the bucket private.
resource "aws_s3_bucket_public_access_block" "site" {
  bucket                  = aws_s3_bucket.site.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Encryption at rest with S3-managed keys (SSE-S3).
resource "aws_s3_bucket_server_side_encryption_configuration" "site" {
  bucket = aws_s3_bucket.site.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Content-Type for each file extension, so browsers render the pages correctly.
locals {
  site_dir = "${path.module}/../site"
  mime = {
    html = "text/html"
    css  = "text/css"
    js   = "application/javascript"
    png  = "image/png"
  }
}

# Upload every file from ../site to the bucket.
resource "aws_s3_object" "files" {
  for_each     = fileset(local.site_dir, "**")
  bucket       = aws_s3_bucket.site.id
  key          = each.value
  source       = "${local.site_dir}/${each.value}"
  etag         = filemd5("${local.site_dir}/${each.value}") # upload again when the file changes
  content_type = lookup(local.mime, reverse(split(".", each.value))[0], "binary/octet-stream")
}

# Origin Access Control: only CloudFront can read the private bucket.
resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "${var.project}-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# AWS managed cache policy for static content.
data "aws_cloudfront_cache_policy" "optimized" {
  name = "Managed-CachingOptimized"
}

resource "aws_cloudfront_distribution" "site" {
  enabled             = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200" # this price class includes edge locations in India
  comment             = "${var.project} CDN"
  # web_acl_id = aws_wafv2_web_acl.x.arn  # optional AWS WAF; Shield Standard is already on

  origin {
    domain_name              = aws_s3_bucket.site.bucket_regional_domain_name
    origin_id                = "s3-site"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-site"
    viewer_protocol_policy = "redirect-to-https" # encryption in transit
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = data.aws_cloudfront_cache_policy.optimized.id
    compress               = true
  }

  # A private bucket returns 403 for a missing key. Show the friendly error page instead.
  custom_error_response {
    error_code         = 403
    response_code      = 404
    response_page_path = "/error.html"
  }

  restrictions {
    geo_restriction { restriction_type = "none" }
  }

  viewer_certificate {
    cloudfront_default_certificate = true # *.cloudfront.net HTTPS certificate
  }
}

# Resource-based policy: allow reads only from this one distribution.
resource "aws_s3_bucket_policy" "site" {
  bucket     = aws_s3_bucket.site.id
  depends_on = [aws_s3_bucket_public_access_block.site]
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "AllowCloudFrontOAC"
      Effect    = "Allow"
      Principal = { Service = "cloudfront.amazonaws.com" }
      Action    = "s3:GetObject"
      Resource  = "${aws_s3_bucket.site.arn}/*"
      Condition = { StringEquals = { "AWS:SourceArn" = aws_cloudfront_distribution.site.arn } }
    }]
  })
}

# Open this URL in a browser after terraform apply.
output "site_url" {
  description = "HTTPS URL of the CloudFront distribution"
  value       = "https://${aws_cloudfront_distribution.site.domain_name}"
}

# Try the direct S3 URL in a browser too. It should fail with AccessDenied, which shows the bucket is private.
output "bucket_name" {
  description = "Private S3 bucket that holds the site"
  value       = aws_s3_bucket.site.bucket
}

output "distribution_id" {
  description = "Use this ID for cache invalidations"
  value       = aws_cloudfront_distribution.site.id
}

