client = boto3.client("bedrock-agent-runtime", region_name="us-east-1")

KB_ID = "YOUR_KB_ID"  # from the Bedrock console after syncing S3 PDFs
MODEL_ARN = "arn:aws:bedrock:us-east-1::foundation-model/amazon.nova-lite-v1:0"

def ask(question, session_id=None):
    kwargs = {
        "input": {"text": question},
        "retrieveAndGenerateConfiguration": {
            "type": "KNOWLEDGE_BASE",
            "knowledgeBaseConfiguration": {
                "knowledgeBaseId": KB_ID,
                "modelArn": MODEL_ARN,
                "retrievalConfiguration": {
                    "vectorSearchConfiguration": {"numberOfResults": 5}
                },
            },
        },
    }
    if session_id:
        kwargs["sessionId"] = session_id  # keeps chat history
    resp = client.retrieve_and_generate(**kwargs)
    sources = [ref["location"] for c in resp.get("citations", [])
               for ref in c["retrievedReferences"]]
    return resp["output"]["text"], sources, resp["sessionId"]

