  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Guardrails for Amazon Bedrock: applied to the user input and the model output
resource "aws_bedrock_guardrail" "chat" {
  name                      = "pdf-chat-guardrail"
  blocked_input_messaging   = "Sorry, I cannot help with that request."
  blocked_outputs_messaging = "Sorry, I cannot share that answer."

  content_policy_config {
    filters_config {
      type            = "HATE"
      input_strength  = "HIGH"
      output_strength = "HIGH"
    }
    filters_config {
      type            = "PROMPT_ATTACK" # jailbreak / prompt injection detection
      input_strength  = "HIGH"
      output_strength = "NONE" # prompt attack filter applies to input only
    }
  }

  topic_policy_config {
    topics_config {
      name       = "InvestmentAdvice"
      type       = "DENY" # denied topic
      definition = "Recommendations to buy or sell specific stocks or financial products."
      examples   = ["Which shares should I buy this week?"]
    }
  }

  sensitive_information_policy_config {
    pii_entities_config {
      type   = "EMAIL"
      action = "ANONYMIZE" # mask PII instead of blocking the whole reply
    }
  }
}

# Immutable version that the app references
resource "aws_bedrock_guardrail_version" "v1" {
  guardrail_arn = aws_bedrock_guardrail.chat.guardrail_arn
  description   = "v1"
}

