"""Terminal chat over your PDFs using Bedrock Knowledge Bases (RAG) and a guardrail."""
import os

import boto3
from dotenv import load_dotenv

load_dotenv()
# Runtime client: RetrieveAndGenerate = retrieve chunks + augment prompt + generate
rt = boto3.client("bedrock-agent-runtime", region_name=os.environ["AWS_REGION"])

# Prompt engineering: clear role, grounding rule and fallback; $search_results$ is required
PROMPT = (
    "You are a helpful assistant. Answer ONLY using the search results below. "
    "If the answer is not in them, say 'I could not find that in the documents.' "
    "Keep answers under 150 words.\n\n$search_results$"
)

CONFIG = {
    "type": "KNOWLEDGE_BASE",
    "knowledgeBaseConfiguration": {
        "knowledgeBaseId": os.environ["KB_ID"],
        "modelArn": os.environ["MODEL_ARN"],
        # Number of chunks retrieved from the vector store
        "retrievalConfiguration": {"vectorSearchConfiguration": {"numberOfResults": 5}},
        "generationConfiguration": {
            "promptTemplate": {"textPromptTemplate": PROMPT},
            "guardrailConfiguration": {
                "guardrailId": os.environ["GUARDRAIL_ID"],
                "guardrailVersion": os.environ["GUARDRAIL_VERSION"],
            },
            # Inference parameters: low temperature for factual answers
            "inferenceConfig": {
                "textInferenceConfig": {"temperature": 0.2, "topP": 0.9, "maxTokens": 512}
            },
        },
    },
}


def main() -> None:
    session_id = None  # Bedrock keeps conversation context per session
    while True:
        question = input("\nYou: ").strip()
        if question.lower() in ("exit", "quit"):
            break
        if not question:
            continue
        kwargs = {"input": {"text": question}, "retrieveAndGenerateConfiguration": CONFIG}
        if session_id:
            kwargs["sessionId"] = session_id
        resp = rt.retrieve_and_generate(**kwargs)
        session_id = resp["sessionId"]
        print("Bot:", resp["output"]["text"])
        # Citations show which PDF each part of the answer came from (transparency)
        sources = {
            ref["location"]["s3Location"]["uri"]
            for c in resp.get("citations", [])
            for ref in c.get("retrievedReferences", [])
            if "s3Location" in ref.get("location", {})
        }
        for uri in sorted(sources):
            print("  source:", uri)


if __name__ == "__main__":
    main()

