import json
import os
import uuid
from datetime import datetime, timezone
from decimal import Decimal

import boto3
from boto3.dynamodb.conditions import Key

# Init code runs once per execution environment (cold start) and is reused on warm invokes.
TABLE = boto3.resource("dynamodb").Table(os.environ["TABLE_NAME"])


def _resp(status, body):
    # HTTP API payload format 2.0 response
    return {
        "statusCode": status,
        "headers": {"content-type": "application/json"},
        "body": json.dumps(body, default=str),  # Decimal -> string
    }


def create_order(event):
    try:
        body = json.loads(event.get("body") or "{}", parse_float=Decimal)  # DynamoDB needs Decimal, not float
    except json.JSONDecodeError:
        return _resp(400, {"error": "body must be JSON"})
    customer_id = body.get("customerId")
    amount = body.get("amount")
    if not customer_id or not isinstance(amount, (int, Decimal)) or amount <= 0:
        return _resp(400, {"error": "customerId and positive amount are required"})

    order_id = str(uuid.uuid4())
    created = datetime.now(timezone.utc).isoformat()
    item = {
        "PK": f"CUSTOMER#{customer_id}",
        "SK": f"ORDER#{created}#{order_id}",   # ISO time in SK keeps orders sorted by date
        "orderId": order_id,
        "amount": amount,
        "status": "PLACED",
        "createdAt": created,
    }
    # Conditional write: never overwrite an existing item with the same key
    TABLE.put_item(Item=item, ConditionExpression="attribute_not_exists(SK)")
    return _resp(201, item)


def list_orders(event):
    customer_id = event["pathParameters"]["customerId"]
    # Query (not Scan): reads one partition only, so cost stays low as the table grows
    result = TABLE.query(
        KeyConditionExpression=Key("PK").eq(f"CUSTOMER#{customer_id}")
        & Key("SK").begins_with("ORDER#"),
        ScanIndexForward=False,  # newest first
        Limit=25,
    )
    return _resp(200, {"orders": result["Items"], "next": result.get("LastEvaluatedKey")})


def handler(event, context):
    route = event.get("routeKey")  # e.g. "POST /orders" in payload format 2.0
    if route == "POST /orders":
        return create_order(event)
    if route == "GET /customers/{customerId}/orders":
        return list_orders(event)
    return _resp(404, {"error": f"no route {route}"})

