import * as cdk from 'aws-cdk-lib';
import { Construct } from 'constructs';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import * as codedeploy from 'aws-cdk-lib/aws-codedeploy';
import * as cloudwatch from 'aws-cdk-lib/aws-cloudwatch';
import * as apigw from 'aws-cdk-lib/aws-apigateway';

class BlueGreenOrdersStack extends cdk.Stack {
  constructor(scope: Construct, id: string, props?: cdk.StackProps) {
    super(scope, id, props);
    // Change these with -c appVersion=v2 -c failRate=0.5
    const appVersion = String(this.node.tryGetContext('appVersion') ?? 'v1');
    const failRate = String(this.node.tryGetContext('failRate') ?? '0');

    const fn = new lambda.Function(this, 'OrdersFn', {
      runtime: lambda.Runtime.NODEJS_22_X,
      handler: 'handler.handler',
      code: lambda.Code.fromAsset('src', { exclude: ['pretraffic.js'] }),
      environment: { APP_VERSION: appVersion, FAIL_RATE: failRate },
    });

    // currentVersion publishes a new version whenever code or env changes
    const alias = new lambda.Alias(this, 'LiveAlias', {
      aliasName: 'live',
      version: fn.currentVersion,
    });

    // Monitoring: any error on the live alias in a 1-minute window = rollback
    const errorsAlarm = new cloudwatch.Alarm(this, 'AliasErrors', {
      metric: alias.metricErrors({ period: cdk.Duration.minutes(1), statistic: 'Sum' }),
      threshold: 1,
      evaluationPeriods: 1,
      treatMissingData: cloudwatch.TreatMissingData.NOT_BREACHING,
    });

    // Pre-traffic hook: smoke-tests the green version before any user traffic
    const preHook = new lambda.Function(this, 'PreTrafficHook', {
      runtime: lambda.Runtime.NODEJS_22_X,
      handler: 'pretraffic.handler',
      code: lambda.Code.fromAsset('src', { exclude: ['handler.js'] }),
      timeout: cdk.Duration.seconds(30),
      environment: { TARGET_VERSION_ARN: fn.currentVersion.functionArn },
    });
    fn.grantInvoke(preHook); // covers the function and its versions

    const group = new codedeploy.LambdaDeploymentGroup(this, 'OrdersDG', {
      alias,
      deploymentConfig: codedeploy.LambdaDeploymentConfig.CANARY_10PERCENT_5MINUTES,
      alarms: [errorsAlarm],
      preHook,
      autoRollback: { failedDeployment: true, deploymentInAlarm: true },
    });
    group.grantPutLifecycleEventHookExecutionStatus(preHook);

    // The API always calls the alias, so CodeDeploy controls the traffic split
    const api = new apigw.LambdaRestApi(this, 'OrdersApi', { handler: alias });
    new cdk.CfnOutput(this, 'ApiUrl', { value: api.url });
  }
}

const app = new cdk.App();
new BlueGreenOrdersStack(app, 'BlueGreenOrders', {
  env: { account: process.env.CDK_DEFAULT_ACCOUNT, region: process.env.CDK_DEFAULT_REGION },
});

// Orders service. The version under release is set by APP_VERSION.
const version = process.env.APP_VERSION || 'v1';
const failRate = Number(process.env.FAIL_RATE || '0');

exports.handler = async (event) => {
  // Health checks from the PreTraffic hook skip the simulated failure.
  // This lets the demo show alarm-based rollback during the canary.
  const isHealthCheck = event && event.healthCheck === true;

  if (!isHealthCheck && Math.random() < failRate) {
    // Unhandled error -> Lambda Errors metric -> AliasErrors alarm -> rollback
    throw new Error(`Simulated failure in ${version}`);
  }

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      service: 'orders',
      version,
      checkedAt: new Date().toISOString(),
    }),
  };
};

// CodeDeploy BeforeAllowTraffic hook. It must report a status, or the deployment times out.
// AWS SDK v3 is included in the Node.js 22 Lambda runtime.
const { CodeDeployClient, PutLifecycleEventHookExecutionStatusCommand } = require('@aws-sdk/client-codedeploy');
const { LambdaClient, InvokeCommand } = require('@aws-sdk/client-lambda');

const codedeploy = new CodeDeployClient({});
const lambda = new LambdaClient({});

exports.handler = async (event) => {
  const { DeploymentId, LifecycleEventHookExecutionId } = event;
  let status = 'Succeeded';

  try {
    // Invoke the new (green) version directly, not the alias
    const res = await lambda.send(new InvokeCommand({
      FunctionName: process.env.TARGET_VERSION_ARN,
      Payload: Buffer.from(JSON.stringify({ healthCheck: true })),
    }));
    if (res.FunctionError) throw new Error(`Function error: ${res.FunctionError}`);

    const body = JSON.parse(Buffer.from(res.Payload).toString());
    if (body.statusCode !== 200) throw new Error(`Unexpected status ${body.statusCode}`);
    console.log('Smoke test passed', body.body);
  } catch (err) {
    console.error('Smoke test failed', err);
    status = 'Failed'; // CodeDeploy stops and keeps blue serving 100%
  }

  await codedeploy.send(new PutLifecycleEventHookExecutionStatusCommand({
    deploymentId: DeploymentId,
    lifecycleEventHookExecutionId: LifecycleEventHookExecutionId,
    status,
  }));
  return status;
};

