import unittest
from datetime import date

from checklist import checklist
from planner import add_years, exam_minutes
from resume import resume_lines


class PlannerTests(unittest.TestCase):
    def test_three_year_validity(self):
        self.assertEqual(add_years(date(2025, 3, 10), 3), date(2028, 3, 10))

    def test_leap_day(self):
        self.assertEqual(add_years(date(2024, 2, 29), 3), date(2027, 2, 28))

    def test_esl_adds_30_minutes(self):
        self.assertEqual(exam_minutes(130, False, True), 160)
        self.assertEqual(exam_minutes(180, True, False), 180)

    def test_must_request_esl_before_booking(self):
        self.assertIsNone(exam_minutes(130, False, False))

    def test_onvue_has_system_test(self):
        self.assertTrue(any("system test" in i for i in checklist("onvue")))

    def test_unknown_delivery_rejected(self):
        with self.assertRaises(ValueError):
            checklist("home")

    def test_resume_flags_unclaimed_badge(self):
        data = {"certifications": [{"code": "CLF-C02", "name": "AWS Certified Cloud Practitioner",
                                    "passed_on": "2025-03-10", "credly_url": "https://www.credly.com/badges/REPLACE"}]}
        self.assertIn("claim your Credly badge", resume_lines(data)[1])


if __name__ == "__main__":
    unittest.main()
